    while (now < T0 + 90000 && !(z.state.state === ST.ACTIVE && z.ghosts.some((g) => g.on && !g.dying))) tick();
    const W = G.TARGET_WIDTH, rows = z.targets(new Float64Array(G.TARGET_SLOTS * W)), out = {};
