const cupRun = `(() => { const B = window.__ooga, R = B.race, T = window.BL.raceTrack.TRACKS, rounds = []; R.startCup(); for (let i = 0; i < T.length; i++) { if (i) R.nextRace(); const P = B.racers; P.start(); P.autopilot = true; R.simulate(300); P.autopilot = false; rounds.push({ track: R.selection.track, field: P.racers.map((r) => r.name).join(), all: P.order.every((r) => r.finished), ranked: P.order.every((r, k) => r.rank === k + 1 && (!k || P.order[k - 1].finishTime <= r.finishTime)) }); R.finishRace(); } const pts = Array.from(R.cup.points), you = pts[B.racers.player.index], lo = pts.filter((p) => p > you).length + 1, hi = pts.filter((p) => p >= you).length, stored = B.game.state.race.cup, place = stored ? ["gold", "silver", "bronze"].indexOf(stored.medal) + 1 : 0; const saved = stored ? stored.points === you && place >= lo && place <= hi : hi > 3; return { ok: R.cup.done && R.phase === "finished" && B.racers.racers.length === Math.min(window.BL.racers.FIELD, B.racers.all.length) && rounds.every((r) => r.all && r.ranked && r.field === rounds[0].field) && saved && T.every((t) => B.game.state.race.best[t.id]), rounds, you, lo, hi, stored }; })()`;
// The diver starts 40 up and 56 back along its heading from the target; its glide carries it onto it.
const dropRun = `(() => { const B = window.__ooga, D = B.drop; D.jumpNow(); const T = B.course.target, d = B.diver.state, h = Math.atan2(T.x, T.z); B.diver.place(T.x - Math.sin(h) * 56, T.y + 40, T.z - Math.cos(h) * 56, h); B.diver.jump(0, 0, 0, h); let pulled = false; for (let t = 0; t < 120 && D.phase !== "results"; t += 0.25) { if (!pulled && D.phase === "air" && d.p.y < T.y + 75) { D.deploy(); pulled = true; } D.simulate(0.25); } const r = D.result, best = B.game.state.drop.best; return { ok: D.phase === "results" && !!r && r.score > 0 && r.medal === window.BL.dropHud.medalFor(r.score) && !!best && best.score === r.score, phase: D.phase, result: r && { score: r.score, landing: r.landing, medal: r.medal } }; })()`;
// Eight GPU rigs for two minutes, out to the island mid-run and a reload: the run comes back as saved and
// then finishes to its results, score shown and kept as the best, the run's save cleared.
const mineResume = { name: "mine save and finish", why: "playthrough: a mine run survives leaving and a reload, then finishes to its results", run: async (b) => {
  // The page seeds the mine's dice from the clock, and some seeds roll an early rug pull that pays nothing;
  // a saved run with a fixed seed is loaded exactly as a player's save is, so every run rolls the same.
  await b.evaluate(`(() => { const sim = window.BL.mineSim.create({ seed: 7 }); sim.simulate(1); window.BL.mineSim.save(sim, ""); })()`);
  await b.open(sceneUrl("mine"));
  await untilReady(b);
  const bought = await b.evaluate(`(() => { const M = window.__ooga.mine; if (M.phase !== "run") M.start(); M.setBananas(1e5); let n = 0; while (n < 8 && M.buy("m1", -1)) n++; M.simulate(120); return n; })()`);
  await tourGo(b, "hub");
  const saved = await b.evaluate(`(() => { const raw = localStorage.getItem("oogaboogaland.mine"), s = raw && JSON.parse(raw).state; return s && { time: s.time, mined: s.minedSats, unit: JSON.stringify(s.unit) }; })()`);
  await b.open(sceneUrl("mine"));
  await untilReady(b);
  const resumed = await b.evaluate(`(() => { const s = window.__ooga.mine.state; return { phase: window.__ooga.mine.phase, time: s.time, mined: s.minedSats, unit: JSON.stringify(Array.from(s.unit)) }; })()`);
  record("mine save: a run left mid-way is saved and a reload resumes it where it stood", bought === 8 && !!saved && resumed.phase === "run" && resumed.unit === saved.unit && resumed.time >= saved.time && resumed.time < saved.time + 10 && resumed.mined >= saved.mined, JSON.stringify({ bought, saved: saved && { time: saved.time, mined: saved.mined }, resumed: { phase: resumed.phase, time: resumed.time, mined: resumed.mined } }));
  const r = await b.evaluate(`(() => { const B = window.__ooga, M = B.mine, s = M.state; M.sim.end(); M.simulate(0.25); const shown = +document.getElementById("mine-final-score").textContent.replace(/[^0-9]/g, ""), best = B.game.state.mine.best; return { ok: s.minedSats > 0 && M.phase === "results" && shown === s.score && !!best && best.score === s.score && localStorage.getItem("oogaboogaland.mine") === null, phase: M.phase, mined: s.minedSats, shown, score: s.score }; })()`);
  // The score counts whole hundredths of a coin, so a short run may score 0; what is proven is that coin was
  // mined and the score shown is the run's own.
  record("mine playthrough: the resumed run finishes to its results with the score shown, kept as the best and its save cleared", r.ok, JSON.stringify(r));
} };

// Steering is measured on screen, never derived: A/D shipped mirrored in the rally and Q/E in the drop,
// and the canopy once turned Q right while freefall was correct. Each key is held through the real
// keyboard listener for fixed frames and its drift projected on the camera's screen-right, relative to
// the same run with no key. `ev` holds a key the way the page hears it.
const EV = `const ev = (t, k) => window.dispatchEvent(new KeyboardEvent(t, { key: k }));`;
const raceSteer = (keys) => `(() => { const B = window.__ooga, R = B.race; ${EV} const out = {};
  for (const k of [null, ...${JSON.stringify(keys)}]) {
    R.startRace(); B.advance(3.6, 1 / 60); ev("keydown", "w"); B.advance(1.2, 1 / 60);
    const p = B.racers.player, h0 = p.heading, x0 = p.x, z0 = p.z, fx = Math.sin(h0), fz = Math.cos(h0);
    // The lined-up grid (draw=0) leaves a rival touching the player, whose contact push would read as steering: rivals
    // sit out the measured half second (racers.js skips a respawning racer in every step and collision).
    for (const o of B.racers.racers) if (o !== p) o.respawn = 0.6;
    if (k) ev("keydown", k); B.advance(0.5, 1 / 60); if (k) ev("keyup", k); ev("keyup", "w");
    const along = (p.x - x0) * fx + (p.z - z0) * fz, sp = B.project(p.x, p.y + 0.5, p.z, {}), ss = B.project(x0 + fx * along, p.y + 0.5, z0 + fz * along, {});
    out[k || "none"] = +(sp.x - ss.x).toFixed(1);
  }
  return out; })()`;
const raceStart = { name: "race start and steering", why: "regression: A and D steered the kart the wrong way on screen", run: async (b) => {
  const st = () => b.evaluate(`({ phase: window.__ooga.race.phase, card: !document.querySelector('[data-intro="race"]').hidden })`);
  const fresh = await st();
  await b.key("Enter");
  const closed = await st();
  await b.key("Enter");
  const counting = await st();
  await b.evaluate(`window.__ooga.advance(3.6, 1 / 60)`);
  const racing = await st();
  const px = await b.evaluate(raceSteer(["a", "d", "ArrowLeft", "ArrowRight"]));
  record("race start and steering: Enter closes the title card, Enter starts the countdown into the race, and A, D and the arrows steer left and right on screen", fresh.card && fresh.phase === "garage" && !closed.card && closed.phase === "garage" && counting.phase === "countdown" && racing.phase === "racing" && px.none === 0 && px.a < -50 && px.ArrowLeft < -50 && px.d > 50 && px.ArrowRight > 50, JSON.stringify({ fresh, closed, counting, racing, px }));
} };
const raceRigs = { name: "race rig poses", why: "regression: the full custom driver field exceeded the global GPU record budget before a rebuilt track even rendered", run: async (b) => {
  const r = await b.evaluate(`(() => {
    const B = __ooga, gl = B.renderer.kind === "webgl2", rows = [], poses = [], originalTrack = B.race.selection.track, originalMount = B.race.selection.mount;
    B.race.toGarage();
    const rigs = B.racers.racers.map(racer => racer.node.geometry?.meshRig);
    const matrices = rigs.map(rig => rig?.matrices);
    for (const id of ["bay", "gorge", "peak", "bay"]) {
      document.querySelector('[data-track="' + id + '"]').click(); B.advance(1 / 60, 1 / 60); B.housekeep();
      rows.push({ id, records: B.renderer.stats.records, racers: B.racers.all.length });
    }
    for (const mount of ["run", "dino", "kart"]) {
      document.querySelector('[data-mount="' + mount + '"]').click(); B.advance(1 / 60, 1 / 60);
      let exact = true, complete = true;
      for (let i = 0; i < B.racers.racers.length; i++) {
        const racer = B.racers.racers[i], rig = racer.node.geometry?.meshRig;
        if (gl) {
          exact &&= rig === rigs[i] && rig.matrices === matrices[i] && rig.nodes.length === 9;
          for (let j = 0; j < rig.nodes.length; j++) for (let k = 0; k < 16; k++) exact &&= rig.matrices[j * 16 + k] === Math.fround(rig.nodes[j].world[k]);
          complete &&= rig.sources.every((source, j) => source === rig.nodes[j].geometry && source.faces.length > 0);
        } else complete &&= !rig && ["legR", "legL", "torso", "armR", "armL", "club", "head", "fingersR", "fingersL"].every(key => racer.cave.parts[key].geometry.faces.length > 0 && !racer.cave.parts[key].meshRigSource);
      }
      poses.push({ mount, exact, complete });
    }
    document.querySelector('[data-track="' + originalTrack + '"]').click(); document.querySelector('[data-mount="' + originalMount + '"]').click(); B.advance(1 / 60, 1 / 60);
    return { gl, rows, poses, ready: B.renderer.ready, failure: B.renderer.failure };
  })()`);
  record("race rigs: every rendered track keeps the unchanged global GPU record cap with the full cast and every CPU joint follows its mount", r.ready && !r.failure && r.rows.every(row => row.records < 320 && row.racers === CAST) && r.poses.every(pose => pose.exact && pose.complete), JSON.stringify(r));
} };
const raceRigContext = { name: "race rig context restoration", why: "regression: restored WebGL records must rebuild joint streams without replacing CPU poses or dropping custom racers", run: async (b) => {
  const r = await b.evaluate(`new Promise((resolve, reject) => {
    const B = __ooga, canvas = document.getElementById("scene"), gl = canvas.getContext("webgl2"), ext = gl && gl.getExtension("WEBGL_lose_context");
    if (!ext) return reject(new Error("Race context-loss extension unavailable"));
    B.race.toGarage(); B.advance(1 / 60, 1 / 60); B.housekeep();
    const before = B.renderer.stats.records, frames = B.renderedFrames;
    const saved = B.racers.racers.map(racer => { const geometry = racer.node.geometry, rig = geometry.meshRig; return { racer, geometry, rig, nodes: rig.nodes.slice(), sources: rig.sources.slice(), matrices: rig.matrices, params: rig.params, voxels: rig.voxels, voxelValues: Array.from(rig.voxels), visibility: rig.visibility }; });
    const originalBuffer = gl.createBuffer, originalVao = gl.createVertexArray;
    let buffers = 0, vaos = 0, lost = false, restored = false, done = false, restoreTimer;
    gl.createBuffer = function(...args) { buffers++; return originalBuffer.apply(this, args); };
    gl.createVertexArray = function(...args) { vaos++; return originalVao.apply(this, args); };
    const cleanup = () => { done = true; clearTimeout(timer); clearTimeout(restoreTimer); canvas.removeEventListener("webglcontextlost", onLost); canvas.removeEventListener("webglcontextrestored", onRestored); gl.createBuffer = originalBuffer; gl.createVertexArray = originalVao; };
    const timer = setTimeout(() => { cleanup(); reject(new Error("Race WebGL context restoration exceeded 15000ms")); }, 15000);
    const onLost = () => { lost = gl.isContextLost(); restoreTimer = setTimeout(() => ext.restoreContext(), 100); };
    const onRestored = () => { restored = true; requestAnimationFrame(check); };
    const check = () => {
      if (done) return;
      if (!B.renderer.ready || B.renderedFrames <= frames + 2 || B.renderer.stats.drawn <= 0) return requestAnimationFrame(check);
      B.housekeep();
      let identities = B.racers.racers.length === saved.length, exact = true, voxelsFinite = true;
      for (const entry of saved) {
        const rig = entry.rig;
        identities &&= entry.racer.node.geometry === entry.geometry && entry.geometry.meshRig === rig && rig.matrices === entry.matrices && rig.params === entry.params && rig.voxels === entry.voxels && rig.visibility === entry.visibility;
        identities &&= rig.nodes.length === 9 && rig.nodes.every((node, j) => node === entry.nodes[j] && node.geometry === entry.sources[j] && rig.sources[j] === entry.sources[j] && node.meshRigSource === rig && node.geometry.faces.length > 0);
        for (let j = 0; j < rig.nodes.length; j++) for (let k = 0; k < 16; k++) exact &&= rig.matrices[j * 16 + k] === Math.fround(rig.nodes[j].world[k]);
        voxelsFinite &&= Array.from(rig.voxels).every((value, j) => Number.isFinite(value) && value === entry.voxelValues[j]);
      }
      const result = { lost, restored, contextLost: gl.isContextLost(), before, records: B.renderer.stats.records, drawn: B.renderer.stats.drawn, ready: B.renderer.ready, failure: B.renderer.failure, framesBefore: frames, framesAfter: B.renderedFrames, racers: saved.length, field: window.BL.racers.FIELD, buffers, vaos, identities, exact, voxelsFinite, error: gl.getError() };
      cleanup(); resolve(result);
    };
    canvas.addEventListener("webglcontextlost", onLost); canvas.addEventListener("webglcontextrestored", onRestored); ext.loseContext();
  })`);
  record("race rigs: a real WebGL context loss rebuilds GPU records for the whole field within the unchanged cap while preserving CPU sources and joint palettes", r.lost && r.restored && !r.contextLost && r.ready && !r.failure && r.drawn > 0 && r.records > 0 && r.records < 320 && r.before < 320 && r.racers === Math.min(r.field, CAST) && r.buffers >= CAST * 2 && r.vaos >= CAST && r.identities && r.exact && r.voxelsFinite && r.error === 0, JSON.stringify(r));
} };
const racePause = { name: "race pause", why: "rule: Escape pauses the race and nothing moves until it is pressed again", run: async (b) => {
  await b.evaluate(`(() => { const B = window.__ooga; ${EV} B.race.startRace(); B.advance(3.6, 1 / 60); ev("keydown", "w"); B.advance(1, 1 / 60); })()`);
  await b.key("Escape");
  const held = await b.evaluate(`(() => { const B = window.__ooga, P = B.racers, pos = () => P.racers.map((r) => [r.x, r.z]); const a = pos(), t = P.raceTime, phase = B.race.phase, panel = !document.getElementById("race-pause").hidden; B.advance(2, 1 / 60); const moved = Math.max(...pos().map((p, i) => Math.hypot(p[0] - a[i][0], p[1] - a[i][1]))); return { phase, panel, moved, clock: P.raceTime - t }; })()`);
  await b.key("Escape");
  const going = await b.evaluate(`(() => { const B = window.__ooga, p = B.racers.player, x = p.x, z = p.z, phase = B.race.phase; B.advance(0.5, 1 / 60); window.dispatchEvent(new KeyboardEvent("keyup", { key: "w" })); return { phase, moved: Math.hypot(p.x - x, p.z - z) }; })()`);
  record("race pause: Escape pauses with the pause panel up and no racer or clock moving, and Escape again drives on", held.phase === "paused" && held.panel && held.moved === 0 && held.clock === 0 && going.phase === "racing" && going.moved > 1, JSON.stringify({ held, going }));
} };
// A signed-in contributor drives only their own Ooga on the island, so the garage holds them to it. The account
// is set on the page's own `BL.net.state`, as /api/me leaves it before a garage opens; signing out clears it.
const raceOwn = { name: "race own ooga", why: "rule: a signed-in visitor with an Ooga races only it, and signing out brings the picker back", run: async (b) => {
  const r = await b.evaluate(`(() => { const B = window.__ooga, R = B.race, P = B.racers, net = window.BL.net;
    const rows = () => [...document.querySelectorAll("#garage-racers li")].filter((li) => !li.hidden).map((li) => li.querySelector("button").dataset.racer);
    const before = R.selection.racer, c = window.BL.characters.all().find((c) => c.handle !== before && P.all.some((r) => r.name === c.handle));
    net.state.me = { id: 1, login: c.github || c.handle, display: c.handle };
    R.toGarage();
    const signedIn = { rows: rows(), picked: R.selection.racer, player: P.player.name, last: P.racers[P.racers.length - 1] === P.player, help: document.getElementById("garage-pick-ooga").hidden };
    net.state.me = null;
    R.toGarage();
    const signedOut = { rows: rows().length, help: !document.getElementById("garage-pick-ooga").hidden };
    document.querySelector('#garage-racers [data-racer="' + before + '"]').click();
    return { own: c.handle, signedIn, signedOut, restored: P.player.name === before };
  })()`);
  record("race own ooga: a signed-in visitor's garage offers only their own Ooga and races it, and signing out offers every Ooga again", r.signedIn.rows.length === 1 && r.signedIn.rows[0] === r.own && r.signedIn.picked === r.own && r.signedIn.player === r.own && r.signedIn.last && r.signedIn.help && r.signedOut.rows === CAST && r.signedOut.help && r.restored, JSON.stringify(r));
} };
// Picking judges a racer's head and torso by their ancestors, so an Ooga off the field must hang, body and all,
// under its hidden racer node; one never seated once floated detached and visible at a stale place.
const raceBench = { name: "race bench", why: "regression: Oogas never drawn into the field stayed pickable at stale transforms", run: async (b) => {
  const r = await b.evaluate(`(() => { const P = window.__ooga.racers, field = new Set(P.racers);
    const bench = P.all.filter((r) => !field.has(r));
    return { built: P.all.length, field: field.size, bench: bench.length, detached: P.all.filter((r) => r.cave.root.parent !== r.node).map((r) => r.name).slice(0, 5), shownOff: bench.filter((r) => r.node.visible).length, hiddenOn: P.racers.filter((r) => !r.node.visible).length };
  })()`);
  record("race bench: every Ooga's body hangs under its racer, and only the field is shown", r.built === CAST && r.bench === CAST - r.field && r.bench > 0 && r.detached.length === 0 && r.shownOff === 0 && r.hiddenOn === 0, JSON.stringify(r));
} };
// A signed-in contributor drives only their own Ooga on the island, so each game holds them to it on entering. The
// account is set on the page's own `BL.net.state`, as /api/me leaves it before a scene opens; signing out clears it,
// and the next visit hands the choice back. The signed-in visit comes from the arcade, the other from the island, so
// the exit names each. `read` returns what the game shows; `held` judges it.
const ownOoga = (id, read, held) => ({ name: `${id} own ooga`, why: "rule: a signed-in visitor with an Ooga plays only it, signing out hands the choice back, and the exit names where it goes", run: async (b) => {
  const exit = `document.querySelector('nav[data-scene="${id}"] .leave').textContent`;
  let own, signedIn, signedOut;
  try {
    own = await b.evaluate(`(() => { const list = window.BL.contributors.activeRoster, c = window.BL.characters.all().find((c) => c.handle !== list[0].name && list.some((r) => r.name === c.handle)); window.BL.net.state.me = { id: 1, login: c.github || c.handle, display: c.handle }; return { handle: c.handle, display: window.BL.characters.displayOf(c.handle) }; })()`);
    await tourGo(b, "arcade");
    await tourGo(b, id);
    signedIn = { ...await b.evaluate(read), exit: await b.evaluate(exit) };
  } finally {
    await b.evaluate(`window.BL.net.state.me = null`);
  }
  await tourGo(b, "hub");
  await tourGo(b, id);
  signedOut = { ...await b.evaluate(read), exit: await b.evaluate(exit) };
  record(`${id} own ooga: a signed-in visitor plays their own Ooga and nothing else, signing out hands the choice back, and the exit says Back to arcade from a cabinet and Back to the island from the island`, held(own, signedIn, signedOut) && signedIn.exit === "Back to arcade" && signedOut.exit === "Back to the island", JSON.stringify({ own, signedIn, signedOut }));
} });
const dropOwn = ownOoga("drop", `({ who: document.querySelector('#drop-oogas [aria-pressed="true"]').dataset.racer, rows: [...document.querySelectorAll("#drop-oogas li")].filter((li) => !li.hidden).length, help: !document.getElementById("drop-pick-ooga").hidden })`,
  (own, i, o) => i.who === own.handle && i.rows === 1 && !i.help && o.rows === CAST && o.help);
