      N.remotes.set(99446, peer(99446, 4)); N.remotes.set(99447, peer(99447, -4));
      Object.assign(slot, { on: true, id: 99446, inGame: 1 });
      B.advance(0.5, 1 / 60);
      const [hunter, spectator] = caves;
