    const ix = -sx * 0.6 + sz * 0.8, iz = -sz * 0.6 - sx * 0.8, facing = Math.atan2(ix, iz);
    let buriedFrames = 0, movingFrames = 0, previousX = x, previousZ = z;
    state.trace = [];
